      "module": "Mathlib.GroupTheory.Congruence.Hom"
    },
    {
      "name": "AddCon.comapQuotientEquivOfSurj",
      "type": " {M : Type u_1} {N : Type u_2} [AddZeroClass M] [AddZeroClass N] (c : AddCon M) (f : N →+ M) (hf : Function.Surjective ⇑f) : (AddCon.comap ⇑f ⋯ c).Quotient ≃+ c.Quotient",
      "module": "Mathlib.GroupTheory.Congruence.Basic"
    },
    {
      "name": "AddCon.comapQuotientEquiv",
      "type": " {M : Type u_1} {N : Type u_2} [AddZeroClass M] [AddZeroClass N] (c : AddCon M) (f : N →+ M) : (AddCon.comap ⇑f ⋯ c).Quotient ≃+ ↥(AddMonoidHom.mrange (c.mk'.comp f))",
      "module": "Mathlib.GroupTheory.Congruence.Basic"
    },
    {
      "name": "AddCon.comapQuotientEquivOfSurj_mk",
      "type": " {M : Type u_1} {N : Type u_2} [AddZeroClass M] [AddZeroClass N] (c : AddCon M) {f : N →+ M} (hf : Function.Surjective ⇑f) (x : N) : (c.comapQuotientEquivOfSurj f hf) ↑x = ↑(f x)",
