      "name": "AddCon.comapQuotientEquivOfSurj_symm_mk",
      "type": " {M : Type u_1} {N : Type u_2} [AddZeroClass M] [AddZeroClass N] (c : AddCon M) {f : N →+ M} (hf : Function.Surjective ⇑f) (x : N) : (c.comapQuotientEquivOfSurj f hf).symm ↑(f x) = ↑x",
